      8: [{ week: 8, keyword: "jump", question: "The dancer will _______ over the box easily.", options: ["comedy"], answer: "C", explanation: "jump 跳\n/dʒʌmp/ → \"jump\"\n巩固词汇：jump意为“跳跃”" },{ week: 8, keyword: "straight back", question: "Always keep a _______ when you dance so you look tall.", options: ["jump", "turn", "straight back", "wand"], answer: "C", explanation: "巩固词汇：straight back意为“挺直的背”" },],
      9: [{ week: 9, keyword: "scissor jump", question: "A jump where your legs open and close like blades is a _______.", options: ["scissor jump", "comedy", "turn", "wand"], answer: "A", explanation: "scissor jump意为“剪⼑跳”" },{ week: 9, keyword: "straight back", question: "Do a scissor jump but keep a _______ so you don't fall forward.", options: ["comedy", "straight back", "spell", "turn"], answer: "B", explanation: "巩固词汇：straight back意为“挺直的" },],
      10: [{ week: 10, keyword: "scissor jump", question: "Open your legs wide in the air to do a beautiful _______.", options: ["wand", "spell", "scissor jump", "comedy"], answer: "C", explanation: "巩固词汇：scissor jump意为“剪⼑跳”" },{ week: 10, keyword: "straight back", question: "Sit up with a _______ before the show starts.", options: ["straight back", "scissor jump", "wand", "audience"], answer: "A", explanation: "巩固词汇：straight back意为“挺直的背”" },],
      11: [{ week: 11, keyword: "comedy", question: "A funny play that makes everyone laugh is a _______.", options: ["comedy", "jump"], answer: "C", explanation: "comedy意为“喜剧”" },{ week: 11, keyword: "exciting", question: "An action movie with lots of jumping and running is very _______.", options: ["boring", "exciting", "straight", "scissor"], answer: "B", explanation: "exciting意为“令⼈兴奋的”" },],
      12: [{ week: 12, keyword: "comedy", question: "The clown's jokes were perfect for this funny _______.", options: ["comedy", "straight back", "wand", "turn"], answer: "A", explanation: "巩固词汇：comedy意为“喜剧”" },{ week: 12, keyword: "exciting", question: "Winning the talent show was a very _______ moment!", options: ["straight", "jump"], answer: "B", explanation: "巩固词汇：exciting意为“令⼈兴奋的”" },],
      13: [{ week: 13, keyword: "comedy", question: "My stomach hurt from laughing so much at the _______.", options: ["wand", "comedy", "jump", "spell"], answer: "B", explanation: "巩固词汇：comedy意为“喜剧”" },{ week: 13, keyword: "exciting", question: "The fast dance music made the performance very _______.", options: ["sad", "boring", "exciting", "straight"], answer: "C", explanation: "巩固词汇：exciting意为“令⼈兴奋的”" },],
      14: [{ week: 14, keyword: "comedy", question: "If you like to smile and laugh, you will love this _______.", options: ["comedy", "straight back", "jump", "scissor"], answer: "A", explanation: "巩固词汇：comedy意为“喜剧”" },{ week: 14, keyword: "exciting", question: "The magic trick at the end of the show was so _______!", options: ["boring", "exciting", "straight back", "sad"], answer: "B", explanation: "巩固词汇：exciting意为“令⼈兴奋的”" },],
      15: [{ week: 15, keyword: "review", question: "What do we do to show we are paying attention to the teacher?", options: ["Give a bow", "Lose energy", "Show full focus", "Make a gentle sound"], answer: "C", explanation: "review 回顾\n/rɪˈvjuː/ → \"ri-VYOO\"\n注意⼒集中即表现出全神贯注 focus", passage: "We rehearse our song and have good teamwork. We look at the teacher with full focus. We sing with high energy to make a strong sound. The audience loves it and we bow on the stage." },],
