      7: [{ week: 7, keyword: "sketch", question: "A quick, simple drawing done with a pencil is a _______.", options: ["sketch", "symmetry", "mixing", "abstract"], answer: "A", explanation: "sketch 草图\n/sketʃ/ → \"skech\"\nsketch意为“素描/草图”" },],
      8: [{ week: 8, keyword: "memory", question: "Something you remember in your mind from the past is a _______.", options: ["pattern", "memory", "expression", "rhythm"], answer: "B", explanation: "memory意为“记忆”" },{ week: 8, keyword: "culture", question: "Traditional art and stories of a group of people make up their _______.", options: ["mixing", "sketch", "culture", "abstract"], answer: "C", explanation: "culture 文化\n/ˈkʌltʃə(r)/ → \"KUL-chuh\"\nculture意为“⽂化”" },],
      9: [{ week: 9, keyword: "memory", question: "I painted a happy picture of my favorite childhood _______.", options: ["mixing", "memory", "symmetry"], answer: "C", explanation: "巩固词汇：memory意为“记忆”" },],
      10: [{ week: 10, keyword: "culture", question: "We share art and traditions from our native _______.", options: ["culture", "mixing"], answer: "C", explanation: "culture 文化\n/ˈkʌltʃə(r)/ → \"KUL-chuh\"\n巩固词汇：culture意为“⽂化”" },],
      11: [{ week: 11, keyword: "pattern", question: "A design that repeats shapes and colors is a _______.", options: ["memory", "culture", "pattern", "rhythm"], answer: "C", explanation: "pattern 图案\n/ˈpætn/ → \"PAT-uhn\"\npattern意为“图案/规律”" },],
      13: [{ week: 13, keyword: "mixing", question: "Putting yellow and blue paint together to make green is color _______.", options: ["mixing", "symmetry", "rhythm", "abstract"], answer: "A", explanation: "mixing意为“混合”" },],
      14: [{ week: 14, keyword: "abstract", question: "A painting of floating colorful squares is an _______ artwork.", options: ["symmetry", "rhythm", "portrait"], answer: "A", explanation: "abstract 抽象的\n/ˈæbstrækt/ → \"AB-strakt\"\n巩固词汇：abstract意为“抽象的”" },{ week: 14, keyword: "expression", question: "Showing your inside feelings in your art is an _______ of yourself.", options: ["abstract", "symmetry", "expression", "rhythm"], answer: "B", explanation: "expression 表达\n/ɪkˈspreʃn/ → \"ik-SPRESH-uhn\"\nexpression意为“表达/表现”" },],
      15: [{ week: 15, keyword: "review", question: "How an actor uses their body to move and show their character is their _______.", options: ["lines", "stage left", "physicality", "script"], answer: "C", explanation: "review 回顾\n/rɪˈvjuː/ → \"ri-VYOO\"\n使⽤⾝体动作来表现即为 physicality", passage: "The actor walks to stage right with strong physicality. She shows a happy facial expression and begins to speak her lines loudly." },],
